#' @export
bsdt <- function(
    case_a = 35,
    case_b = 48,
    controls_a = 50,
    controls_b = 50,
    sd_a = 10,
    sd_b = 10,
    sample_size = 20,
    correlation = 0.5,
    alternative = "two.sided",
    unstandardised = FALSE,
    credible_interval = TRUE,
    credible_level = 95,
    iter = 10000,
    seed = 42,
    show_plot = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("bsdt requires jmvcore to be installed (restart may be required)")


    options <- bsdtOptions$new(
        case_a = case_a,
        case_b = case_b,
        controls_a = controls_a,
        controls_b = controls_b,
        sd_a = sd_a,
        sd_b = sd_b,
        sample_size = sample_size,
        correlation = correlation,
        alternative = alternative,
        unstandardised = unstandardised,
        credible_interval = credible_interval,
        credible_level = credible_level,
        iter = iter,
        seed = seed,
        show_plot = show_plot)

    analysis <- bsdtClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

